
function ImprimirFactura(cliente, NroCbtefactura, CodigoAfip) {
    if (CodigoAfip != 99) {
        
        $.getJSON("/Cliente/GetFacturaJson",
            { idCliente: cliente, idComprobante: NroCbtefactura },
            function (resp) {
                

            if (resp.result) {
                var facturaJson = JSON.parse(resp.data);
                var funcStr = "factura";
                var doc = ComprobantesCliente[funcStr](facturaJson);
                document.getElementById("output").src = doc.output('datauristring');

                var Buque = facturaJson.Header;
                var index = Buque.indexOf('-');
                if (index < 0) {
                    subcadena = '';
                } else {
                    subcadena = facturaJson.Header.substring(0, index);
                }
                var NroCbte = facturaJson.NumeroComprobante;

                var n = "Comprobante_" + subcadena + " # " + NroCbte;

//                var n = "Comprobante_"
                doc.save(n);
                }
                $("#modalFactura").modal('show');
            });
    }
 }




