ComprobantesCliente.factura = function (facturaJson) {

    var doc = new jsPDF("portrait", "mm", "a4");
    doc.setProperties({
        title: 'SAC',
        subject: 'Pandi',
        author: 'Pandi',
        keywords: 'Dev-All',
        creator: 'SAC'
    });

    AgregarPagina(doc, facturaJson, "ORIGINAL");
    //  doc.addPage()
    //AgregarPagina(doc, facturaJson, "DUPLICADO");
    return doc;
}

